fn complete_multi_value_tag(args: &[&str]) -> Vec<CompletionCandidate> {
    let mut cmd = multi_value_tag_cmd();
    let args: Vec<std::ffi::OsString> = args.iter().map(std::ffi::OsString::from).collect();
